 p=R/reg;d=pd.read_parquet(p/'additional_primary2010_layer.parquet');s=d[d.strict_uid.notna()].copy();s['id']=s.strict_uid;s['population_for_root_review']=s.population_2010_with_control_derived_zero;s['proposed_primary_value_quality']=s.derived_zero_from_exhaustive_same_scope_controls.map({True:'reviewed_primary_control_derived_zero',False:'reviewed_primary_reported_value'})
 a=next(a for a in acq if a['id']==reg+'_allNP_archive');s['source_original_official_URL']=a['original_official_url'];s['source_archived_retrieval_URL']=a['final_url'];s['source_archive_sha256']=a['sha256'];s['source_control_proof_receipt']=str(p/'derived_zero_proof_receipt.json');s['population_minus_original_including_derived_zero']=s.population_for_root_review-s.baseline_original_secondary_population
 assert s.id.is_unique and s.population_for_root_review.notna().all() and s.population_for_root_review.ge(0).all();path=p/f'immutable_source_review_candidates_{reg}_{len(s)}_20261021_v1.parquet';assert not path.exists();s.to_parquet(path,index=False)
 receipt={'path':str(path),'rows':len(s),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'columns':list(s.columns),'strict_ID_unique':True,'literal_numeric':int(s.primary_population.notna().sum()),'derived_control_zero':int(s.derived_zero_from_exhaustive_same_scope_controls.sum()),'previous_quality_counts':s.baseline_original_quality.value_counts().to_dict(),'numeric_corrections_including_derived_zero':int(s.population_minus_original_including_derived_zero.ne(0).sum()),'root_adoption_required':True,'master_or_axis_modified':False,'source':a,'source_controls':json.loads((p/'derived_zero_proof_receipt.json').read_text())};(p/'immutable_review_candidates_v1_receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');receipts.append({k:v for k,v in receipt.items()if k in ['path','rows','sha256','literal_numeric','derived_control_zero','previous_quality_counts','numeric_corrections_including_derived_zero']})
